      strategyBridge: `\u5B66\u4E60\u5165\u53E3\u80FD\u5E2E\u52A9\u4F60\u66F4\u5BB9\u6613\u5F00\u59CB\u548C\u7406\u89E3\uFF1B\u73B0\u5728\u9700\u8981\u9A8C\u8BC1\u7684\u662F\uFF1A${STRATEGY_PURPOSE[strategy.id]}\uFF0C\u6240\u4EE5\u672C\u5468\u5148\u7EC3\u201C${strategy.studentLabel}\u201D\u3002`,
